#!/usr/bin/env python3
"""RoboLab food_packing2_cans episode controller; run commands as this episode unfolds."""
import sys, time, json
sys.path.insert(0, '/opt/tools')
import numpy as np
from PIL import Image
from rcb_client import Robot, EpisodeOver

OUT='/app/output'
DOWN=np.array([0.0,-2**-0.5,2**-0.5,0.0], dtype=float)

def connect():
    r=Robot()
    print('status',json.dumps(r.status()))
    return r

def recover(r, exc):
    print('service connection failure; waiting for same episode:', repr(exc), flush=True)
    st=r.wait_ready()
    print('resumed status',json.dumps(st), flush=True)
    return st

def observe(r, tag='obs', depth=True):
    o=r.get_obs(depth=depth, video='none')
    for cam,img in o.last.items(): Image.fromarray(img).save(f'{OUT}/{tag}_{cam}.png')
    if depth:
        for cam,d in o.last_depth.items(): np.save(f'{OUT}/{tag}_{cam}_depth.npy', d)
    print('obs',tag,'step',o.meta.get('control_steps'),'time_left',o.meta.get('time_left_s'),'tcp',o.meta['proprio']['now'][8:15], flush=True)
    return o

def move(r, xyz, grip=0, quat=DOWN, note='move'):
    p=np.r_[np.asarray(xyz,dtype=float),np.asarray(quat,dtype=float),float(grip)]
    res=r.submit('ee_pose',p,video='frames',video_fps=5,note=note)
    print(note,'step',res.meta.get('control_steps_chunk'), 'done',res.meta.get('done'),'reason',res.meta.get('reason'),'plan',res.meta.get('plan'),'proprio',res.meta.get('proprio',{}).get('now',[None]*11)[8:11],flush=True)
    return res

def stage_soup_approach(r):
    # Top-down, above the red tomato soup can. Depth calibration puts it near (0.414, 0.003).
    res=move(r,[0.414,0.003,0.235],0,note='approach above tomato soup can')
    res.save(f'{OUT}/soup_approach')
    observe(r,'after_soup_approach',False)

if __name__=='__main__':
    stage=sys.argv[1] if len(sys.argv)>1 else 'observe'
    r=connect()
    try:
        if stage=='observe': observe(r,'current')
        elif stage=='soup_approach': stage_soup_approach(r)
        else: raise SystemExit('unknown stage '+stage)
    except Exception as e:
        print(type(e).__name__,str(e),flush=True)
        try: recover(r,e)
        except Exception as ee: print('recovery failed',repr(ee),flush=True)
        raise
